#!/usr/bin/env bash
#: SWARMER, A UNIVERSAL AGENT SWARM FOR CODING AGENTS, version 5.3
#: (Claude Code, Codex, Antigravity, Gemini CLI, and every tool that reads AGENTS.md and Agent Skills)
#:
#: One file: the swarm's documents, its database of professionals and its engine, plus the commands to install
#: and convene it.
#:
#: Needs: bash, python3 >= 3.8 (standard library only), and a coding agent (`claude`, `codex`, `agy`, `gemini`, ...).
#:
#:   bash swarmer.sh install [--language en|it] [--targets claude,codex,...|auto] [--instructions] [--folder DIR]
#:   bash swarmer/swarmer.sh <single|fan-out|classic|jury|light-jury|full|plenary|expert|auto> "request"
#:   bash swarmer/swarmer.sh help            # every command, in the chosen language
#:   bash swarmer/swarmer.sh extensions --add crossroads   # the decision graph and the way back (an extension)
#:
#: Commands and options have aliases in every available language (see help).

set -euo pipefail

THIS="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)/$(basename "${BASH_SOURCE[0]}")"

# @aliases-begin
# Generated by «build» from i18n/*.json and engine/compat.py: do not edit by hand.
canonical_command() {
    case "$1" in
        'install'|'installa') printf '%s' 'install' ;;
        'update'|'aggiorna') printf '%s' 'update' ;;
        'help'|'-h'|'--help'|'aiuto') printf '%s' 'help' ;;
        'tests'|'prove') printf '%s' 'tests' ;;
        *) printf '%s' "$1" ;;
    esac
}
canonical_option() {
    case "$1" in
        '--folder'|'--cartella') printf '%s' '--folder' ;;
        '--language'|'--lingua') printf '%s' '--language' ;;
        '--local'|'--locale') printf '%s' '--local' ;;
        '--instructions'|'--istruzioni') printf '%s' '--instructions' ;;
        '--force'|'--forza') printf '%s' '--force' ;;
        '--project-managed'|'--gestiti-dal-progetto') printf '%s' '--project-managed' ;;
        '--targets'|'--destinazioni') printf '%s' '--targets' ;;
        *) printf '%s' "$1" ;;
    esac
}
msg_en() {
    case "$1" in
        cli_prefix) printf '%s' 'swarmer: ' ;;
        sh_bad_folder) printf '%s' 'folder not allowed in {path}: {folder}' ;;
        sh_incomplete) printf '%s' 'this file is incomplete: download it again' ;;
        sh_missing_python) printf '%s' 'python3 is missing or too old (3.8 or newer is needed)' ;;
        sh_needs_folder) printf '%s' '-C wants a folder' ;;
        sh_needs_value) printf '%s' '{option}: a value is needed' ;;
        sh_not_a_project) printf '%s' '{root} does not look like a project: -C FOLDER install' ;;
        sh_not_installed) printf '%s' 'the swarm is not installed in {root} yet: bash swarmer.sh install' ;;
        sh_unknown_option) printf '%s' '{command}: unknown option: {option}' ;;
        sh_unsafe_name) printf '%s' 'this file contains an unsafe file name ({path}): not installing it' ;;
        *) printf '%s' "$1" ;;
    esac
}
msg_it() {
    case "$1" in
        cli_prefix) printf '%s' 'sciame: ' ;;
        sh_bad_folder) printf '%s' 'cartella non ammessa in {path}: {folder}' ;;
        sh_incomplete) printf '%s' 'questo file è incompleto: scaricalo di nuovo' ;;
        sh_missing_python) printf '%s' 'manca python3, o è troppo vecchio (serve il 3.8 o più recente)' ;;
        sh_needs_folder) printf '%s' '-C vuole una cartella' ;;
        sh_needs_value) printf '%s' '{option}: serve un valore' ;;
        sh_not_a_project) printf '%s' '{root} non sembra un progetto: -C CARTELLA installa' ;;
        sh_not_installed) printf '%s' 'in {root} lo sciame non c'\''è ancora: bash sciame.sh installa' ;;
        sh_unknown_option) printf '%s' '{command}: opzione sconosciuta: {option}' ;;
        sh_unsafe_name) printf '%s' 'questo file contiene un nome di file non ammesso ({path}): non lo installo' ;;
        *) printf '%s' "$1" ;;
    esac
}
default_folder() {
    case "$1" in
        it) printf '%s' 'sciame' ;;
        *) printf '%s' 'swarmer' ;;
    esac
}
LANGUAGES=('en' 'it')
SWARM_FOLDERS=('swarmer' 'sciame')
STATE_DIRS=('.swarmer' '.sciame')
FOLDER_KEYS=('folder' 'cartella')
ROOT_FILES=('ROOT' 'RADICE')
FACTORY_FILES=('FACTORY.json' 'FABBRICA.json')
LANGUAGE_FILES=('LANGUAGE' 'LINGUA')
ENGINES=('engine/swarmer.py' 'motore/sciame.py')
LANGUAGE_ENVS=('SWARMER_LANGUAGE' 'SCIAME_LINGUA')
# @aliases-end

SH_LANG="en"

# A message of bash in the language: msg KEY [NAME VALUE]…
msg() {
    local k="$1" m; shift
    if declare -F "msg_$SH_LANG" >/dev/null; then m="$("msg_$SH_LANG" "$k")"; else m="$(msg_en "$k")"; fi
    while [ $# -ge 2 ]; do m="${m//\{$1\}/$2}"; shift 2; done
    printf '%s' "$m"
}

fail() { printf '%s%s\n' "$(msg cli_prefix)" "$*" >&2; exit 1; }

need_python() {
    command -v python3 >/dev/null 2>&1 || fail "$(msg sh_missing_python)"
    python3 -I -B -c 'import sys; sys.exit(0 if sys.version_info >= (3, 8) else 1)' || fail "$(msg sh_missing_python)"
}

# The files at the end of this file, into a folder.
extract() {
    # A file name is relative, without «..», without empty components: otherwise the extraction stops (code 2).
    awk -v dest="$1" '
        /^#==== swarmer\.sh: file [A-Za-z0-9_.\/-]+ ====$/ {
            if (out) close(out)
            name = $4
            if (name ~ /^\// || name ~ /(^|\/)\.\.(\/|$)/ || name ~ /\/\// || (name in seen)) { bad = name; exit 2 }
            seen[name] = 1
            out = dest "/" name
            d = out; sub(/\/[^\/]*$/, "", d); system("mkdir -p \"" d "\"")
            printf "" > out; next }
        /^#==== swarmer\.sh: end of files ====$/ { if (out) close(out); out = ""; next }
        out { print > out }
        END { if (bad != "") exit 2 }
    ' "$THIS" || fail "$(msg sh_unsafe_name)"
    [ -f "$1/engine/swarmer.py" ] && [ -f "$1/db/professionals.json" ] || fail "$(msg sh_incomplete)"
}

# The first of a list of names that exists in a folder: first_in DIR NAME…
first_in() {
    local d="$1" n; shift
    for n in "$@"; do [ -e "$d/$n" ] && { printf '%s' "$n"; return 0; }; done
    return 1
}

# An installed copy has ROOT, FACTORY.json and the engine, under the new or the old names (an interrupted
# migration has some of each).
is_install() {
    first_in "$1" "${ROOT_FILES[@]}" >/dev/null && first_in "$1" "${FACTORY_FILES[@]}" >/dev/null \
        && first_in "$1" "${ENGINES[@]}" >/dev/null
}

# The swarm folder from the configuration of the project, validated: relative, without «..», not «.»; otherwise the
# installed one (swarmer/, then the others), otherwise the default of the language.
folder_from_config() {
    local r="$1" want="${2:-}" found=() d f x
    for d in "${STATE_DIRS[@]}"; do [ -e "$r/$d" ] && found+=("$d"); done
    [ "${#found[@]}" -le 1 ] || fail "both $r/${found[0]} and $r/${found[1]} exist"
    if [ "${#found[@]}" -eq 1 ]; then
        f="$r/${found[0]}/config.json"
        if [ -f "$f" ] && [ ! -L "$f" ]; then
            x="$(python3 -I -B -c '
import json, os, sys
c = json.load(open(sys.argv[1], encoding="utf-8"))
keys = [k for k in sys.argv[2:] if isinstance(c, dict) and k in c]
if len(keys) > 1:
    sys.exit("both %r and %r in %s" % (keys[0], keys[1], sys.argv[1]))
if keys:
    v = c[keys[0]]
    parts = str(v).split("/")
    if not isinstance(v, str) or not v or os.path.isabs(v) or ".." in parts or v in (".", "./") or "" in parts:
        sys.exit("folder not allowed in %s: %r" % (sys.argv[1], v))
    print(v, end="")' "$f" "${FOLDER_KEYS[@]}")" || exit 1
            [ -n "$x" ] && { printf '%s' "$x"; return; }
        fi
    fi
    for x in "${SWARM_FOLDERS[@]}"; do
        first_in "$r/$x" "${FACTORY_FILES[@]}" >/dev/null && { printf '%s' "$x"; return; }
    done
    default_folder "${want:-$(env_language)}"
}

env_language() {
    local v
    for v in "${LANGUAGE_ENVS[@]}"; do [ -n "${!v:-}" ] && { printf '%s' "${!v}"; return; }; done
    printf 'en'
}

# The language of the messages: LANGUAGE, then the 4.0 file, then the environment, then en.
set_language() {
    local d="$ROOT_DIR/$SWARM_DIR" n l=""
    for n in "${LANGUAGE_FILES[@]}"; do
        if [ -f "$d/$n" ] && [ ! -L "$d/$n" ]; then l="$(head -c 8 "$d/$n" | tr -d '\n')"; break; fi
    done
    [ -n "$l" ] || l="$(env_language)"
    case "$l" in [a-z][a-z]) SH_LANG="$l" ;; *) SH_LANG="en" ;; esac
}

# The swarm folder: the one of this file if it is an installed copy, otherwise the one of the configuration of the
# project, otherwise the installed one, otherwise <project>/swarmer (the default of the language).
find_install() {
    local here want="${1:-}"; here="$(dirname "$THIS")"
    if [ -n "${ROOT_DIR:-}" ]; then
        ROOT_DIR="$(cd "$ROOT_DIR" && pwd -P)"
        SWARM_DIR="$(folder_from_config "$ROOT_DIR" "$want")" || exit 1
    elif is_install "$here"; then
        ROOT_DIR="$(cd "$here/$(cat "$here/$(first_in "$here" "${ROOT_FILES[@]}")")" && pwd -P)"
        SWARM_DIR="$(python3 -I -B -c 'import os,sys; print(os.path.relpath(sys.argv[1], sys.argv[2]))' "$here" "$ROOT_DIR")"
    else
        ROOT_DIR="$PWD"
        SWARM_DIR="$(folder_from_config "$ROOT_DIR" "$want")" || exit 1
    fi
}

install() {
    local command="$1" typed="$2"; shift 2
    need_python
    if [ "$ROOT_DIR" = "/" ] || [ "$ROOT_DIR" = "$(cd "${HOME:-/}" && pwd -P)" ]; then
        fail "$(msg sh_bad_folder root "$ROOT_DIR")"
    fi
    local args=()
    while [ $# -gt 0 ]; do
        case "$(canonical_option "$1")" in
            --folder) [ $# -ge 2 ] || fail "$(msg sh_needs_value option "$1")"; SWARM_DIR="${2%/}"; shift 2 ;;
            --language) [ $# -ge 2 ] || fail "$(msg sh_needs_value option "$1")"; args+=(--language "$2"); shift 2 ;;
            --local) [ $# -ge 2 ] || fail "$(msg sh_needs_value option "$1")"; args+=(--local "$2"); shift 2 ;;
            --instructions) args+=(--instructions); shift ;;
            --force) args+=(--force); shift ;;
            --project-managed) args+=(--project-managed); shift ;;
            --targets) [ $# -ge 2 ] || fail "$(msg sh_needs_value option "$1")"; args+=(--targets "$2"); shift 2 ;;
            *) fail "$(msg sh_unknown_option command "$typed" option "$1")" ;;
        esac
    done
    SWARMER_TMP="$(mktemp -d)"
    trap 'rm -rf "${SWARMER_TMP:-}"' EXIT
    extract "$SWARMER_TMP"
    cp "$THIS" "$SWARMER_TMP/swarmer.sh"
    python3 -I -B "$SWARMER_TMP/engine/swarmer.py" "$command" --from "$SWARMER_TMP" --root "$ROOT_DIR" \
        --folder "$SWARM_DIR" ${args[@]+"${args[@]}"}
}

main() {
    ROOT_DIR=""
    SWARM_DIR=""   # never from the environment: the folder comes from --folder, the installed copy or the config
    if [ "${1:-}" = "-C" ]; then
        if [ $# -lt 2 ]; then
            # no project yet: the language of the installed copy this file belongs to, if it is one
            ROOT_DIR="$(dirname "$THIS")"; SWARM_DIR="."; set_language
            fail "$(msg sh_needs_folder)"
        fi
        ROOT_DIR="$2"; shift 2
    fi
    local typed="${1:-help}" command; command="$(canonical_command "$typed")"
    [ $# -eq 0 ] || shift
    local want="" prev="" a
    for a in "$@"; do
        [ "$prev" = "--language" ] && want="$a"
        prev="$(canonical_option "$a")"
    done
    SH_LANG="$(env_language)"
    find_install "$want"
    set_language
    case "$command" in
        help)
            sed -n 's/^#: \{0,1\}//p' "$THIS"
            if first_in "$ROOT_DIR/$SWARM_DIR" "${ENGINES[@]}" >/dev/null; then
                local l="$SH_LANG"
                [ -f "$ROOT_DIR/$SWARM_DIR/docs/$l/_HELP.txt" ] || l="en"
                [ -f "$ROOT_DIR/$SWARM_DIR/docs/$l/_HELP.txt" ] && cat "$ROOT_DIR/$SWARM_DIR/docs/$l/_HELP.txt"
                # the help lines of the enabled extensions (their i18n key «help»); swarmer.py is run from its source,
                # and puts the engine folder after the standard library itself (5.3.2, K-100 and S18)
                if command -v python3 >/dev/null 2>&1 && [ -f "$ROOT_DIR/$SWARM_DIR/engine/swarmer.py" ]; then
                    python3 -I -B -c 'import runpy, sys, pathlib; s = pathlib.Path(sys.argv[1]).resolve(); g = runpy.run_path(str(s / "engine" / "swarmer.py"), run_name="swarmer_help"); print(g["extensions_help"](s, sys.argv[2]), end="")' \
                        "$ROOT_DIR/$SWARM_DIR" "$l" 2>/dev/null || true
                fi
            fi
            return 0 ;;
        install|update)
            # update: with the files of this swarmer.sh, without touching those changed in the project (they go
            # next to them, .new); a 4.0 installation is migrated.
            install "$command" "$typed" "$@" ;;
        tests)
            need_python
            [ -f "$ROOT_DIR/$SWARM_DIR/engine/swarmer.py" ] || fail "$(msg sh_not_installed root "$ROOT_DIR")"
            local rc=0 p
            for p in "$ROOT_DIR/$SWARM_DIR"/tests/test_*.py; do python3 -I -B "$p" || rc=1; done
            exit "$rc" ;;
        *)
            need_python
            [ -f "$ROOT_DIR/$SWARM_DIR/engine/swarmer.py" ] || fail "$(msg sh_not_installed root "$ROOT_DIR")"
            exec python3 -I -B "$ROOT_DIR/$SWARM_DIR/engine/swarmer.py" --swarm "$ROOT_DIR/$SWARM_DIR" "$command" "$@" ;;
    esac
}

main "$@"
exit
# From here on are the files of the swarm, which «install» writes into the swarm folder. Bash never gets past «exit».
: <<'SWARMER_END_OF_FILES'
#==== swarmer.sh: file engine/aliases.py ====
#!/usr/bin/env python3
"""swarmer: the localized names of the command line (B).

The canonical names of commands, options and values are English. Every language declares its aliases in
`i18n/<l>.json`: `"commands": {"install": ["<alias>"], …}`, `"options": {"--folder": ["--<alias>"], …}`,
`"values": {"strategy": {"single": "<alias>", …}, "form": …, "rule": …, "profile": …, "lane": …}`. The parsers join
the aliases of **every** available language (an Italian command works in an English installation too), with
`allow_abbrev=False` everywhere: abbreviations do not exist. The controlled values of compat.py are aliases too.
Standard library only.
"""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

_HERE = Path(__file__).resolve().parent
# 5.3.2 (K-100, S18): compat is compiled from its source, never from a .pyc, and its engine_path puts this folder right
# after the standard library, every module of it compiled from its source
if not hasattr(sys.modules.get("compat"), "engine_path"):
    _c = type(sys)("compat")
    _c.__file__ = str(_HERE / "compat.py")
    exec(compile((_HERE / "compat.py").read_bytes(), _c.__file__, "exec", dont_inherit=True), _c.__dict__)
    sys.modules["compat"] = _c
sys.modules["compat"].engine_path(_HERE)
import compat as C  # noqa: E402

VALUE_CATEGORIES = ("strategy", "form", "rule", "profile", "lane")


def _as_list(v) -> list[str]:
    if v is None:
        return []
    if isinstance(v, str):
        return [v]
    return [str(x) for x in v]


def _sections(t: dict) -> dict:
    return {"commands": {k: _as_list(v) for k, v in t.get("commands", {}).items()},
            "options": {k: _as_list(v) for k, v in t.get("options", {}).items()},
            "values": {c: {k: _as_list(v) for k, v in m.items()}
                       for c, m in t.get("values", {}).items() if isinstance(m, dict)}}


def _merge(into: dict, sec: dict, core: dict) -> None:
    """An extension's sections join the table; a canonical of the core keeps the core's aliases (an extension never
    adds an alias to a core command, option or value: `verify` reports one that tries, see core_additions)."""
    for k in ("commands", "options"):
        for c, names in sec[k].items():
            if c in core[k]:
                continue
            lst = into[k].setdefault(c, [])
            lst += [x for x in names if x not in lst]
    for cat, m in sec["values"].items():
        for c, names in m.items():
            if c in core["values"].get(cat, {}):
                continue
            lst = into["values"].setdefault(cat, {}).setdefault(c, [])
            lst += [x for x in names if x not in lst]


def core_additions(core: dict, sec: dict) -> list[str]:
    """The aliases an extension section gives to a canonical of the core that the core does not have."""
    out = []
    for k in ("commands", "options"):
        for c, names in sec[k].items():
            if c in core[k]:
                out += [f"«{x}» for the core «{c}»" for x in names if x not in core[k][c]]
    for cat, m in sec["values"].items():
        for c, names in m.items():
            if c in core["values"].get(cat, {}):
                out += [f"«{x}» for the core value «{c}»" for x in names if x not in core["values"][cat][c]]
    return out


def per_language(swarm) -> dict[str, dict]:
    """The alias sections of each i18n file: lang → {"commands", "options", "values"}. The sections of the
    extensions (extensions/*/i18n/<lang>.json, 5.2) join those of the core: one table covers both, and the collision
    checks see both."""
    out = {}
    d = Path(swarm) / "i18n" if swarm else None
    for p in sorted(d.glob("*.json")) if d and d.is_dir() else []:
        try:
            t = json.loads(p.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        out[p.stem] = _sections(t)
    core = {l: json.loads(json.dumps(v)) for l, v in out.items()}
    ext = Path(swarm) / "extensions" if swarm else None
    for p in sorted(ext.glob("*/i18n/*.json")) if ext and ext.is_dir() else []:
        if p.stem not in out:
            continue
        try:
            t = json.loads(p.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        _merge(out[p.stem], _sections(t), core[p.stem])
    return out


def load(swarm) -> dict:
    """The union of the aliases of every language, plus the controlled values of compat.py."""
    al = {"commands": {}, "options": {}, "values": {c: {} for c in VALUE_CATEGORIES}}
    for sec in per_language(swarm).values():
        for k in ("commands", "options"):
            for canon, names in sec[k].items():
                al[k].setdefault(canon, [])
                al[k][canon] += [n for n in names if n != canon and n not in al[k][canon]]
        for cat, m in sec["values"].items():
            for canon, names in m.items():
                lst = al["values"].setdefault(cat, {}).setdefault(canon, [])
                lst += [n for n in names if n != canon and n not in lst]
    for cat in VALUE_CATEGORIES:
        for canon, it in C.VALUES.get(cat, {}).items():
            lst = al["values"].setdefault(cat, {}).setdefault(canon, [])
            if it != canon and it not in lst:
                lst.append(it)
    return al


def command_aliases(al: dict, canon: str) -> list[str]:
    return [a for a in al["commands"].get(canon, []) if not a.startswith("-")]


def option_strings(al: dict, *canons: str) -> list[str]:
    out = []
    for c in canons:
        out += [c] + [a for a in al["options"].get(c, []) if a not in out and a != c]
    return list(dict.fromkeys(out))


def value(al: dict, cat: str, v):
    """The canonical form of a value given as canonical or as an alias of any language."""
    if v is None:
        return None
    m = al["values"].get(cat, {})
    if v in m:
        return v
    for canon, names in m.items():
        if v in names:
            return canon
    return v


def parser(**kw) -> argparse.ArgumentParser:
    kw.setdefault("allow_abbrev", False)
    return argparse.ArgumentParser(**kw)


def subparsers(p: argparse.ArgumentParser, al: dict, dest: str = "command"):
    """A subparser group whose `add(name)` registers the aliases and sets `<dest>` to the canonical name."""
    sp = p.add_subparsers(dest="_" + dest, required=True)

    def add(name: str, **kw):
        q = sp.add_parser(name, aliases=command_aliases(al, name), allow_abbrev=False, **kw)
        q.set_defaults(**{dest: name})
        return q
    return add


def arg(q: argparse.ArgumentParser, al: dict, *names: str, **kw):
    """An option with its aliases (the dest is the one of the first canonical name)."""
    if names and names[0].startswith("-"):
        kw.setdefault("dest", names[0].lstrip("-").replace("-", "_"))
        return q.add_argument(*option_strings(al, *names), **kw)
    return q.add_argument(*names, **kw)


def collisions(per_lang: dict, namespaces: dict[str, dict[str, list[str]]]) -> list[str]:
    """The alias collisions, by namespace (B): an alias equal to a different canonical of the namespace, the same
    alias for two canonicals. `namespaces` maps a name to {"commands": [...]} or {"options": [...]} or
    {"values:<cat>": [...]}."""
    errors = []
    for lang, sec in per_lang.items():
        for ns_name, spec in namespaces.items():
            for kind, canons in spec.items():
                if kind.startswith("values:"):
                    table = sec["values"].get(kind.split(":", 1)[1], {})
                else:
                    table = sec[kind]
                seen = {}
                for canon in canons:
                    for a in table.get(canon, []):
                        if a == canon:
                            continue
                        if a in canons:
                            errors.append(f"i18n/{lang}.json: {ns_name}: the alias «{a}» of «{canon}» is the canonical "
                                          f"name of another")
                        if a in seen and seen[a] != canon:
                            errors.append(f"i18n/{lang}.json: {ns_name}: the alias «{a}» is used for «{seen[a]}» and "
                                          f"«{canon}»")
                        seen.setdefault(a, canon)
    return errors
#==== swarmer.sh: file engine/compat.py ====
#!/usr/bin/env python3
"""swarmer: the dialects of the data and the migration from the 4.0 «sciame».

The only module of the engine that holds Italian words. Everything the code has to recognise from an Italian 4.0
installation lives here, so that the other modules work only on canonical (English) forms:
- the dialect tables of the data written in a project (convenings, juries, outcomes, configuration, database), as
  schemas by path, with `to_canonical` and `to_dialect`;
- the names of the files and folders in the two dialects (`CONVENE_FILES`, `JURY_FILES`, `FILE_NAMES`, `STATE_NAMES`);
- the protocol words of a jury round (`LINE_WORDS`), the controlled values (`VALUES`, `STATES`) and the fixed
  reasons of the engine (`REASONS`);
- the 4.0 markers (`OLD_MARKS`), the reserved Italian ids (`RESERVED_IT`), the old environment variables
  (`ENV_ALIASES`) and the forms of the requesters of the expert register (`normalize_requester`).
It also puts the engine's folders on sys.path (`engine_path`): every other module loads it from its source first.
Standard library only.
"""
from __future__ import annotations

import importlib.machinery
import os
import re
import sys
from pathlib import Path


# --- the engine's folders on sys.path (5.3.2, K-100 and S18) ---

class SourceLoader(importlib.machinery.SourceFileLoader):
    """A module compiled from its source, never from a .pyc: under -B Python writes no bytecode, but still runs a
    timestamp .pyc of __pycache__ whose header matches the size and the mtime of the source (S18)."""

    def get_code(self, fullname):
        path = self.get_filename(fullname)
        return self.source_to_code(self.get_data(path), path)


def _source_hook():
    """The path hook of the engine's folders (`hook.swarmer_source_dirs`, real paths): for those, a finder of the .py
    files only, loaded by SourceLoader (no .pyc, no extension module); any other entry goes to the next hook."""
    dirs: set = set()

    def hook(entry):
        try:
            entry = os.fsdecode(entry)
            real = os.path.realpath(entry or os.curdir)
        except (OSError, TypeError, ValueError):
            raise ImportError("not a folder of the swarmer engine") from None
        if real not in dirs:
            raise ImportError("not a folder of the swarmer engine")
        return importlib.machinery.FileFinder(entry, (SourceLoader, [".py"]))

    hook.swarmer_source_dirs = dirs
    return hook


def after_stdlib() -> int:
    """The index of sys.path right after the standard library (the folder of os, and lib-dynload); the end of
    sys.path when neither is on it."""
    std = os.path.dirname(os.__file__)
    last = [i for i, p in enumerate(sys.path)
            if isinstance(p, str) and (p == std or os.path.basename(p) == "lib-dynload")]
    return last[-1] + 1 if last else len(sys.path)


def engine_path(folder) -> None:
    """`folder`, an engine or extension folder, on sys.path right after the standard library (unless it is on sys.path
    already), and every module imported from it compiled from its source (5.3.2). So a file named like a stdlib
    module beside the engine never runs in place of the stdlib one (K-100), nor a .pyc, even one of the same size and
    mtime, in place of the source (S18), whichever launch form or swarm (`--swarm`) names the folder."""
    folder = str(folder)
    hook = next((h for h in sys.path_hooks if hasattr(h, "swarmer_source_dirs")), None)
    if hook is None:
        hook = _source_hook()
        sys.path_hooks.insert(0, hook)
    real = os.path.realpath(folder)
    if real not in hook.swarmer_source_dirs:
        hook.swarmer_source_dirs.add(real)
        for k in list(sys.path_importer_cache):    # a finder cached before for this folder would read the .pyc
            try:
                same = isinstance(k, (str, bytes)) and os.path.realpath(os.fsdecode(k) or os.curdir) == real
            except (OSError, TypeError, ValueError):
                same = False
            if same:
                del sys.path_importer_cache[k]
    if folder not in sys.path:
        sys.path.insert(after_stdlib(), folder)


class Error(Exception):
    """The base error of the engine: every module raises it, or a subclass of it."""


# The id regexes read ASCII digits only (5.3.1). Where the 5.3.0 form of one of them (\d Unicode) reads a text that the
# strict form does not, that text writes an id, a number or a version in non-ASCII digits: its reader refuses it with
# an error, and never skips it, so that no check that refused such a text in 5.3.0 now passes in silence (5.3.1,
# third repair round).
NON_ASCII_DIGIT = re.compile(r"[^\D0-9]")
NUMBER = re.compile(r"\d+", re.ASCII)
_WIDE: dict = {}


def wide(rx: re.Pattern) -> re.Pattern:
    """The 5.3.0 form of a strict regex: [0-9] read as any Unicode digit, and no re.ASCII. A detector, never a reader."""
    w = _WIDE.get(rx)
    if w is None:
        w = _WIDE[rx] = re.compile(rx.pattern.replace("[0-9]", r"\d"), rx.flags & ~re.ASCII)
    return w


def refuse_wide(rx: re.Pattern, text: str, where: str, how: str = "match") -> None:
    """Error if the 5.3.0 form of `rx` reads in `text` (with `how`: match, fullmatch, or search for every match) a
    number with a non-ASCII digit."""
    w = wide(rx)
    hits = w.finditer(text) if how == "search" else [getattr(w, how)(text)]
    bad = next((m.group(0) for m in hits if m and NON_ASCII_DIGIT.search(m.group(0))), None)
    if bad is not None:
        raise Error(f"{where}: «{bad.strip()[:60]}» is written with non-ASCII digits: the engine reads the digits 0-9 "
                    "only (5.3.1)")


