          view(r)[d]["live"] == 0 and [f for f in kinds(fs, "SUPERSEDED-STILL-REALIZED") if f[1] == d]
          and [f for f in kinds(fs, "LIVE-DISAGREES") if f[1] == d], fs)
    p = base / "k102n"
